@lru_cache(maxsize=1)
def load_clock_fonts():
    """Decode the bundled LVGL glyph metrics, kerning and bitmaps once."""
    fonts = json.loads(zlib.decompress(base64.b85decode(_FONT_DATA)))
    for font in fonts.values():
        font["bitmap"] = base64.b64decode(font["bitmap"])
        font["glyphs"] = {int(code): tuple(value) for code, value in font["glyphs"].items()}
    return fonts
